using System;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;
namespace Snowglow.Editor {
 [InitializeOnLoad] public static class AlpsRestoreImportedTerrain {
  const string ScenePath="Assets/Scenes/TheAlps.unity",Log="Logs/AlpsRestoreImportedTerrain";
  static AlpsRestoreImportedTerrain(){EditorApplication.update+=Tick;}
  static T[] All<T>(Scene s)where T:Component=>s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<T>(true)).ToArray();
  static void Check(bool ok,string message){if(!ok)throw new InvalidOperationException("Restore imported Alps terrain: "+message);}
  static void Tick(){if(!File.Exists(Log+".request")||EditorApplication.isPlayingOrWillChangePlaymode||EditorApplication.isCompiling||EditorApplication.isUpdating)return;File.Delete(Log+".request");Directory.CreateDirectory(Log);try{Restore();}catch(Exception e){File.WriteAllText(Log+"/Validation.txt","FAIL: "+e);Debug.LogException(e);}}
  static void Restore(){var scene=SceneManager.GetActiveScene();Check(scene.path==ScenePath,"Alps must be open");if(scene.isDirty)Check(EditorSceneManager.SaveScene(scene,Log+"/Unsaved-before-"+DateTime.UtcNow.ToString("yyyyMMdd-HHmmss")+".unity",true),"unsaved backup");Check(EditorSceneManager.SaveScene(scene,Log+"/Before.unity",true),"current scene backup");
   var placement=All<CatalogPlacement>(scene).Single(p=>p.assetId=="alps-rebuild-terrainbase");var filter=placement.GetComponentInChildren<MeshFilter>();var collider=placement.GetComponentInChildren<MeshCollider>();var original=AlpsRebuildAssets.Find("TerrainBase").prefab.GetComponentInChildren<MeshFilter>().sharedMesh;
   var queries=Directory.GetDirectories("Assets/Snowglow/Levels/TheAlps","Rebuild20261117*").Select(p=>p.Replace('\\','/')+"/TerrainQuery.asset").Where(File.Exists).ToArray();Check(queries.Length==1,"one preserved initial-import query");var data=AssetDatabase.LoadAssetAtPath<TerrainData>(queries[0]);Check(original&&original.GetIndexCount(0)==16800&&data&&data.size.x==1000&&data.size.z==1000,"original 5600-triangle kilometre terrain and query");
   var poses=All<Transform>(scene).ToDictionary(t=>GlobalObjectId.GetGlobalObjectIdSlow(t).ToString(),t=>JsonUtility.ToJson(new PoseData(t)));var query=All<Terrain>(scene).Single();var oldMesh=filter.sharedMesh;var oldQuery=query.terrainData;var oldColliderQuery=query.GetComponent<TerrainCollider>().terrainData;var oldCollision=collider.sharedMesh;bool saved=false;
   try{filter.sharedMesh=original;collider.sharedMesh=original;query.terrainData=data;query.GetComponent<TerrainCollider>().terrainData=data;PrefabUtility.RecordPrefabInstancePropertyModifications(filter);EditorUtility.SetDirty(collider);EditorUtility.SetDirty(query);EditorUtility.SetDirty(query.GetComponent<TerrainCollider>());Physics.SyncTransforms();
    foreach(var t in All<Transform>(scene))Check(poses[GlobalObjectId.GetGlobalObjectIdSlow(t).ToString()]==JsonUtility.ToJson(new PoseData(t)),"no object reseating or scale changes");Check(collider.Raycast(new Ray(new Vector3(0,600,0),Vector3.down),out var centre,1000)&&Mathf.Abs(centre.point.y-SnowField.Ground)<.03f,"original imported centre at existing snow datum");Check(!query.drawHeightmap&&!query.GetComponent<TerrainCollider>().enabled,"hidden camera query stays nonphysical");
    Check(EditorSceneManager.SaveScene(scene),"save terrain reference restoration");saved=true;scene=EditorSceneManager.OpenScene(ScenePath);placement=All<CatalogPlacement>(scene).Single(p=>p.assetId=="alps-rebuild-terrainbase");Check(placement.GetComponentInChildren<MeshFilter>().sharedMesh==original&&placement.GetComponentInChildren<MeshCollider>().sharedMesh==original,"source mesh render/collision persisted");Check(All<Terrain>(scene).Single().terrainData==data,"initial height query persisted");CaptureTerrain(scene);EditorSceneManager.OpenScene(ScenePath);File.WriteAllText(Log+"/Validation.txt","PASS: original imported TerrainBase mesh restored for rendering and collision, 5600 triangles / 1000m square; original import Y scale and snow datum retained. Matching initial TerrainQuery restored: "+queries[0]+". Every scene transform unchanged; no mountain/building/road/tree reseating, no snow/source asset edits. Saved/reopened and terrain-only overview captured. No Play or scenery-access acceptance requested.");
   }catch{if(!saved){filter.sharedMesh=oldMesh;collider.sharedMesh=oldCollision;query.terrainData=oldQuery;query.GetComponent<TerrainCollider>().terrainData=oldColliderQuery;Physics.SyncTransforms();}throw;}
  }
  [Serializable] sealed class PoseData {public Vector3 position,scale;public Quaternion rotation;public PoseData(Transform t){position=t.localPosition;rotation=t.localRotation;scale=t.localScale;}}
  static void CaptureTerrain(Scene scene){var terrain=All<CatalogPlacement>(scene).Single(p=>p.assetId=="alps-rebuild-terrainbase");var renderers=All<Renderer>(scene);var enabled=renderers.Select(r=>r.enabled).ToArray();var session=All<PrototypeSession>(scene).Single();var camera=session.CameraRig.view;var at=camera.transform.position;var rotation=camera.transform.rotation;bool ortho=camera.orthographic;float size=camera.orthographicSize,far=camera.farClipPlane;var target=camera.targetTexture;var previous=RenderTexture.active;bool fog=RenderSettings.fog;var cull=camera.layerCullDistances;bool occlusion=camera.useOcclusionCulling;var rt=RenderTexture.GetTemporary(1600,1000,24);
   try{foreach(var r in renderers)r.enabled=r.transform.IsChildOf(terrain.transform);camera.targetTexture=rt;camera.orthographic=true;camera.orthographicSize=650;camera.farClipPlane=3000;camera.layerCullDistances=new float[32];camera.useOcclusionCulling=false;camera.transform.SetPositionAndRotation(new Vector3(-750,1000,-750),Quaternion.Euler(41,45,0));RenderSettings.fog=false;camera.Render();RenderTexture.active=rt;var image=new Texture2D(1600,1000,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1600,1000),0,0);image.Apply();File.WriteAllBytes(Log+"/Terrain.png",image.EncodeToPNG());UnityEngine.Object.DestroyImmediate(image);
   }finally{for(int i=0;i<renderers.Length;i++)if(renderers[i])renderers[i].enabled=enabled[i];camera.transform.SetPositionAndRotation(at,rotation);camera.orthographic=ortho;camera.orthographicSize=size;camera.farClipPlane=far;camera.targetTexture=target;camera.layerCullDistances=cull;camera.useOcclusionCulling=occlusion;RenderSettings.fog=fog;RenderTexture.active=previous;RenderTexture.ReleaseTemporary(rt);}
  }
 }
}
